// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        address user = address(0x1);
        // Deployer already has all tokens; send some to user
        vm.prank(c._owner());
        c.transfer(user, 1000);
        // Both sender and recipient become allowed roles (bypassing access control)
        // We can't directly call _allowedRoles, but we can set up via the contract's own logic.
        // The only way to set _allowedRoles is through a public function? No, it's private.
        // We'll exploit the fact that the deployer can call transfer with any parameters.
        // Actually, we need both addresses to be in _allowedRoles. Since it's private, we cannot set it externally.
        // The difference lies in the require condition: reference uses require(... || ...), buggy uses require(!... || !...).
        // In the buggy version, if both are true, the require fails. In reference, it passes.
        // So we just need a scenario where both are allowed roles. But we cannot set them.
        // However, the constructor doesn't set any allowed roles. So by default, _allowedRoles[sender] and _allowedRoles[recipient] are false.
        // In the reference, require(sender || recipient) is false => revert. In buggy, require(!sender || !recipient) is true => passes.
        // Wait the reference uses require(_allowedRoles[sender] || _allowedRoles[recipient], "Unauthorized role");
        // If both false, reference reverts. Buggy require(!false || !false) => require(true || true) => true => passes.
        // So the buggy version allows transfer when neither is allowed, while reference reverts.
        // That is the divergence. Let's test it.
        bool ok;
        try c.transfer(user, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok = false), buggy returns true (ok = true).
        // We want the assertion to pass on reference and fail on buggy.
        assertTrue(!ok);
    }
}

